const size_t SECRET_SIZE = 4096;

// Create secret file, ensuring FD is closed on exec
int fd = memfd_secret(FD_CLOEXEC);

if (fd < 0) { /* Check errno: EINVAL, EMFILE */ }

// Set required size for the secret memory region
ftruncate(fd, SECRET_SIZE);

// Map the secret memory into the process address space
void* secret_ptr = mmap(
    NULL,
    SECRET_SIZE,
    PROT_READ | PROT_WRITE,
    MAP_SHARED, // Required for memfd_secret mapping
    fd,
    0
);

// Use secret_ptr...

munmap(secret_ptr, SECRET_SIZE);
close(fd); // File released automatically when all FDs close
